(6467547, 961136, 114565, '<td valign="top">This is just perfect, the detail is awesome, I love it 10+</td>', 'This is just perfect, the detail is awesome, I love it 10+', '2011-07-11 07:15:55.000000', NULL, 1),
(6467548, 961379, 114565, '<td valign="top">This is the 2nd Moon image I have seen and I have to say I am in awe, How do you get these images so clear and detailed?<br/>10+ again, fantastic detail and composition.<br/>Well done</td>', 'This is the 2nd Moon image I have seen and I have to say I am in awe, How do you get these images so clear and detailed?10+ again, fantastic detail and composition.Well done', '2011-07-11 07:18:32.000000', NULL, 1),
