(6467682, 960787, 19825, '<td valign="top">Interesting image and the light on skin is lovely. I am not sure it is well suited for the challenge, but with a nice, well processed image I am not too much of a stickler for rules.</td>', 'Interesting image and the light on skin is lovely. I am not sure it is well suited for the challenge, but with a nice, well processed image I am not too much of a stickler for rules.', '2011-07-11 11:47:29.000000', NULL, 1),
(6467697, 961387, 19825, '<td valign="top">Interesting image. I am not real sure from what perspective we are seeing things. Very cool, though.</td>', 'Interesting image. I am not real sure from what perspective we are seeing things. Very cool, though.', '2011-07-11 12:11:42.000000', NULL, 1),
