(6467945, 961078, 120129, '<td valign="top">very nice work!</td>', 'very nice work!', '2011-07-11 17:03:26.000000', NULL, 1),
(6467988, 960787, 124346, '<td valign="top">Love the texture of the skin, looks like porcelain.  Although the pose is a little unpleasant for me, maybe that pose without the dress could looks to me nicer.  Is that sunlight?</td>', 'Love the texture of the skin, looks like porcelain.  Although the pose is a little unpleasant for me, maybe that pose without the dress could looks to me nicer.  Is that sunlight?', '2011-07-11 18:06:52.000000', NULL, 1),
(6467990, 961279, 124346, '<td valign="top">Fresh, nice, colorfull.  Nice one.</td>', 'Fresh, nice, colorfull.  Nice one.', '2011-07-11 18:07:38.000000', NULL, 1),
(6467991, 961286, 124346, '<td valign="top">Really nice, kinda mysterious.</td>', 'Really nice, kinda mysterious.', '2011-07-11 18:08:08.000000', NULL, 1),
(6467992, 961511, 124346, '<td valign="top">Sunlight behind the tree is really nice, looks heavenly.</td>', 'Sunlight behind the tree is really nice, looks heavenly.', '2011-07-11 18:08:41.000000', NULL, 1),
(6467994, 961160, 124346, '<td valign="top">Really nice, love the colors.</td>', 'Really nice, love the colors.', '2011-07-11 18:10:32.000000', NULL, 1),
(6467996, 961397, 124346, '<td valign="top">It has something special.  I like the sky, nice color, and she stands out with the white dress.  I would try a different framing, just to see another option.</td>', 'It has something special.  I like the sky, nice color, and she stands out with the white dress.  I would try a different framing, just to see another option.', '2011-07-11 18:13:04.000000', NULL, 1),
