(6468001, 961078, 124346, '<td valign="top">Amazing place and great tittle.  Good one.</td>', 'Amazing place and great tittle.  Good one.', '2011-07-11 18:20:23.000000', NULL, 1),
(6468036, 961379, 135267, '<td valign="top">Love this picture.....I would like it as a large print.</td>', 'Love this picture.....I would like it as a large print.', '2011-07-11 19:17:41.000000', NULL, 1),
(6468045, 961396, 133346, '<td valign="top">It might be the late night making me very tired and playing a trick on my eyes, but for a moment I thought there is an optical illusion and the image in it moves towards the right very slowly, and back again.........anyway....even if it is me just being tired and halucinating.....well done!!!!!nice shot and idea!!!love it!!</td>', 'It might be the late night making me very tired and playing a trick on my eyes, but for a moment I thought there is an optical illusion and the image in it moves towards the right very slowly, and back again.........anyway....even if it is me just being tired and halucinating.....well done!!!!!nice shot and idea!!!love it!!', '2011-07-11 20:11:04.000000', NULL, 1),
(6468046, 961368, 133346, '<td valign="top">Where is this place??Is it Southern Italy???lovely shot!!</td>', 'Where is this place??Is it Southern Italy???lovely shot!!', '2011-07-11 20:14:57.000000', NULL, 1),
(6468099, 961500, 66384, '<td valign="top">Love the blur and the colors.</td>', 'Love the blur and the colors.', '2011-07-11 22:58:24.000000', NULL, 1),
(6468101, 961386, 66384, '<td valign="top">Great clarity and DOF.</td>', 'Great clarity and DOF.', '2011-07-11 23:02:59.000000', NULL, 1),
(6468103, 961440, 66384, '<td valign="top">I really like the image and the creativity, but it looks more like a closeup of some leaves, than something from a distance. Perhaps it is a shot of the sun, in which case it would definitely fit the challenge. In any case, it''s hot. :)</td>', 'I really like the image and the creativity, but it looks more like a closeup of some leaves, than something from a distance. Perhaps it is a shot of the sun, in which case it would definitely fit the challenge. In any case, it''s hot. :)', '2011-07-11 23:10:21.000000', NULL, 1),
(6468106, 961296, 66384, '<td valign="top">I like the distance of time as well as the physical distance. Very nice.</td>', 'I like the distance of time as well as the physical distance. Very nice.', '2011-07-11 23:14:21.000000', NULL, 1),
(6468107, 960799, 66384, '<td valign="top">This is dreamy. I love the mood.</td>', 'This is dreamy. I love the mood.', '2011-07-11 23:16:17.000000', NULL, 1),
(6468109, 960876, 66384, '<td valign="top">Classic. Beautiful tones and composition.</td>', 'Classic. Beautiful tones and composition.', '2011-07-11 23:23:06.000000', NULL, 1),
(6468112, 961397, 66384, '<td valign="top">Terrific idea and shot! Too bad about the banding in the sky.</td>', 'Terrific idea and shot! Too bad about the banding in the sky.', '2011-07-11 23:27:39.000000', NULL, 1),
(6468118, 961391, 66384, '<td valign="top">Very amusing.</td>', 'Very amusing.', '2011-07-11 23:44:34.000000', NULL, 1),
(6468122, 961388, 66384, '<td valign="top">I like the shot, the colors, and the edge treatment.</td>', 'I like the shot, the colors, and the edge treatment.', '2011-07-11 23:48:59.000000', NULL, 1),
(6468127, 961078, 66384, '<td valign="top">Delightful! I love the clean processing, the vibrant colors, and the geometric composition.</td>', 'Delightful! I love the clean processing, the vibrant colors, and the geometric composition.', '2011-07-11 23:54:26.000000', NULL, 1),
(6468129, 961435, 66384, '<td valign="top">Love the dreamy feel of this.</td>', 'Love the dreamy feel of this.', '2011-07-11 23:57:38.000000', NULL, 1),
(6468131, 961505, 66384, '<td valign="top">Beautiful tones.</td>', 'Beautiful tones.', '2011-07-11 23:59:09.000000', NULL, 1),
(6468133, 961006, 66384, '<td valign="top">Cool!</td>', 'Cool!', '2011-07-12 00:03:34.000000', NULL, 1),
(6468136, 961387, 66384, '<td valign="top">What a strange effect. It''s lovely.</td>', 'What a strange effect. It''s lovely.', '2011-07-12 00:08:29.000000', NULL, 1),
(6468138, 961172, 66384, '<td valign="top">Nice job of making a beautiful picture out of that tangle of wires.</td>', 'Nice job of making a beautiful picture out of that tangle of wires.', '2011-07-12 00:12:11.000000', NULL, 1),
