(6469728, 961466, 123833, '<td valign="top">A little bit soft but nice idea</td>', 'A little bit soft but nice idea', '2011-07-13 15:54:36.000000', NULL, 1),
(6469729, 961300, 123833, '<td valign="top">Symmetry that works. The colors are saturated but without going over the top.</td>', 'Symmetry that works. The colors are saturated but without going over the top.', '2011-07-13 15:56:51.000000', NULL, 1),
