(6469828, 961213, 135204, '<td valign="top">Amazing and powerful shot.  Fits the challenge perfectly.</td>', 'Amazing and powerful shot.  Fits the challenge perfectly.', '2011-07-13 19:00:00.000000', NULL, 1),
