(6473383, 961354, 86447, '<td valign="top">Yep... beautiful.  9</td>', 'Yep... beautiful.  9', '2011-07-17 20:48:19.000000', NULL, 1),
(6473384, 961507, 86447, '<td valign="top">Fabulous shot!   9</td>', 'Fabulous shot!   9', '2011-07-17 20:48:29.000000', NULL, 1),
