INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6474395, 961192, 112972, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Adz:</b></div><hr/><i> Pleeeaasse can you tell us how you do this kind of processing with the blur? It''s amazing! Congrats </i></td></tr></table> <br/> <br/>Sure, would be happy to.  The glowy/blurry effect is created by NIK''s Glamour Glow.  If you have NIK''s plugin installed in your photoshop, all you have to do is to launch it and click on Glamour Glow and it will give you a very interesting effect like this.  It''s almost like an instant dodge and burn but with a bit of a glow.</td>', 'Originally posted by Adz: Pleeeaasse can you tell us how you do this kind of processing with the blur? It''s amazing! Congrats   Sure, would be happy to.  The glowy/blurry effect is created by NIK''s Glamour Glow.  If you have NIK''s plugin installed in your photoshop, all you have to do is to launch it and click on Glamour Glow and it will give you a very interesting effect like this.  It''s almost like an instant dodge and burn but with a bit of a glow.', '2011-07-18 14:22:49.000000', NULL, 0),
(6474398, 961265, 62357, '<td valign="top">Wonderful shot Lev.  I never seem to have my camera out or I''m over the wing when coming in to land.</td>', 'Wonderful shot Lev.  I never seem to have my camera out or I''m over the wing when coming in to land.', '2011-07-18 14:26:48.000000', NULL, 0),
(6474401, 961265, 30982, '<td valign="top">Wow - the water is amazingly clear!  Love being able to see the underwater formations in this.</td>', 'Wow - the water is amazingly clear!  Love being able to see the underwater formations in this.', '2011-07-18 14:39:15.000000', NULL, 0),
(6474402, 961192, 135419, '<td valign="top">Those trees look so massive!</td>', 'Those trees look so massive!', '2011-07-18 14:42:00.000000', NULL, 0),
(6474403, 961354, 135419, '<td valign="top">Love the shot.</td>', 'Love the shot.', '2011-07-18 14:42:11.000000', NULL, 0),
(6474408, 961507, 48820, '<td valign="top">Thanks to everyone for the votes and great comments.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=28742" rel="nofollow" target="_blank">Art Roflmao</a> <br/>Thanks for coming back to post a nice comment.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=86447" rel="nofollow" target="_blank">LydiaToo</a> <br/>You are such a good girl.  You always say nice things.  Thank you.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=92577" rel="nofollow" target="_blank">hesitant</a> <br/>Me too!  However I was torn since I had several good candidates.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=125275" rel="nofollow" target="_blank">adigitalromance</a> <br/>Yes it''s real and shot from the ground.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=83313" rel="nofollow" target="_blank">Yo_Spiff</a> <br/>Thanks dude.  I appreciate your comments.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=114225" rel="nofollow" target="_blank">giantmike</a> <br/>Yeah man.  It really looks like it a plane to plane shot, huh?<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=123833" rel="nofollow" target="_blank">MargaretN</a> <br/>You are so right!  I''ll have to aske them to do the air show again.  Just for me.  You guys can come too.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=117037" rel="nofollow" target="_blank">galatia_n</a> <br/>Honest to gosh...  You made me go back and look at the challenge write up.  But it really doesn''t say it HAS to be wide.  I have some wide shots that may have done better...  Maybe...<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=12611" rel="nofollow" target="_blank">blindjustice</a> <br/>Thanks!  It was a great day for shooting airplanes...  And sunburn.<br/> <br/><a href="//www.dpchallenge.com/profile.php?USER_ID=36843" rel="nofollow" target="_blank">curtpetguy</a> <br/>Thanks!  It was a fun day.  It was the week of sunburn afterwards that was the hard part.<br/><br/><i>Message edited by author 2011-07-18 17:37:26.</i></td>', 'Thanks to everyone for the votes and great comments. Art Roflmao Thanks for coming back to post a nice comment. LydiaToo You are such a good girl.  You always say nice things.  Thank you. hesitant Me too!  However I was torn since I had several good candidates. adigitalromance Yes it''s real and shot from the ground. Yo_Spiff Thanks dude.  I appreciate your comments. giantmike Yeah man.  It really looks like it a plane to plane shot, huh? MargaretN You are so right!  I''ll have to aske them to do the air show again.  Just for me.  You guys can come too. galatia_n Honest to gosh...  You made me go back and look at the challenge write up.  But it really doesn''t say it HAS to be wide.  I have some wide shots that may have done better...  Maybe... blindjustice Thanks!  It was a great day for shooting airplanes...  And sunburn. curtpetguy Thanks!  It was a fun day.  It was the week of sunburn afterwards that was the hard part.', '2011-07-18 14:46:18.000000', '2011-07-18 18:37:26.000000', 0),
